<?php declare(strict_types=1); namespace Tests\Unit\Services; use App\Services\{NativeProcessRequest,ProcOpenNativeProcessRunner}; use PHPUnit\Framework\TestCase;
final class ProcOpenNativeProcessRunnerTest extends TestCase{public function testItUsesShellFreeArgumentsAndClosesHandles():void{$d=sys_get_temp_dir().'\\tgh-proc-'.bin2hex(random_bytes(4));mkdir($d);$s="$d\\child.php";$in="$d\\in.txt";$out="$d\\out.txt";file_put_contents($s,'<?php fwrite(STDERR,"controlled stderr"); echo json_encode([array_slice($argv,1),stream_get_contents(STDIN)]); exit(7);');file_put_contents($in,'input');$a=[$s,'has spaces','value & echo injected > unexpected-file.txt'];$r=(new ProcOpenNativeProcessRunner)->run(new NativeProcessRequest(PHP_BINARY,$a,$in,$out));self::assertSame(7,$r->exitCode);self::assertStringContainsString('controlled stderr',$r->stderr);$v=json_decode(file_get_contents($out),true);self::assertSame(array_slice($a,1),$v[0]);self::assertSame('input',$v[1]);self::assertFileDoesNotExist($d.'\\unexpected-file.txt');unlink($out);unlink($in);unlink($s);rmdir($d);}}
